1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
30	
31	const componentsBasePremium = (count: number): number =>
32	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
33	
34	const applyFirstInsuranceSurcharge = (amount: number): number =>
35	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
36	
37	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
38	
39	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
40	
41	const isMainItem = (item: Item): boolean => !isComponent(item);
42	
43	const componentsTotalByType = (components: Item[]): number => {
44	  const countsByType = new Map<string, number>();
45	  for (const component of components) {
46	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
47	  }
48	  let total = 0;
49	  for (const count of countsByType.values()) {
50	    total += componentsBasePremium(count);
51	  }
52	  return total;
53	};
54	
55	const itemsBasePremium = (items: Item[]): number => {
56	  const components = items.filter(isComponent);
57	  const mainItems = items.filter(isMainItem);
58	  const mainItemsTotal = mainItems.reduce(
59	    (sum, item) => sum + basePremium(item),
60	    0,
61	  );
62	  return mainItemsTotal + componentsTotalByType(components);
63	};
64	
65	export const quote = (
66	  customer: Customer,
67	  items: Item[],
68	  contractIndex: number,
69	): number => {
70	  const base = itemsBasePremium(items);
71	  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
72	};
73	
74	export const claim = (): number => {
75	  return undefined as unknown as number;
76	};
